@model OrdersViewModel
@{ Layout = "_Layout"; }

<h1>@Model.Title</h1>
<ul>
@foreach (var row in Model.Rows)
{
    <li>@row.Name - @row.Total.ToString("C")</li>
}
</ul>

<partial name="_Footer" model="Model.Footer" />

